import rclpy
from rclpy.node import Node
import os
from std_msgs.msg import String,UInt32
from village_interfaces.srv import BorrowMoney

"""
编写python服务的一般步骤：
1.导入服务接口
2.创建服务端回调函数
3.声明并创建服务端
4.编写回调函数处理逻辑
"""

"""
编写ros2节点的一般步骤：
1. 导入库文件(rclpy和Node类)
2. 创建一个继承自Node的类，并在构造函数中初始化节点名称
3. 在构造函数中创建发布者和订阅者，并设置定时器
4. 定义定时器回调函数和订阅者回调函数
5. 在main函数中初始化rclpy，创建节点实例，并调用rclpy.spin()进入循环，最后调用rclpy.shutdown()关闭节点
"""
class WriterNode(Node):#继承了rclcp.node里的Node类
    def __init__(self,name):
        super().__init__(name)#在这里用super()调用父类的构造函数，初始化节点名称
        #self是当前类的实例对象（即WriterNode），name是节点名称
        self.get_logger().info("Hello everyone,I am a writer,%s." % name)#get_logger()是Node类的一个方法，用于获取节点的日志记录器对象，info()是日志记录器对象的方法，用于输出信息级别的日志消息
        self.pub_novel = self.create_publisher(String, "sexy_girl", 10)
        #create_publisher()是Node类的一个方法，用于创建一个发布者对象，第一个参数是消息类型，第二个参数是话题名称，第三个参数是队列大小
        #队列大小是指在发布者发送消息时，如果订阅者还没有接收到消息，那么这些消息会被存储在一个队列中，队列的大小就是这个队列的最大长度，当队列满了之后，新的消息会覆盖旧的消息，导致旧的消息丢失。
        """
        队列大小
        设置过小：如果发布频率较高，缓冲区很快会被填满，导致新消息覆盖旧消息，造成数据丢失。
        设置过大：虽然能容纳更多消息，但会占用大量内存，并且可能积累大量历史数据，导致订阅者处理严重滞后（延迟增加）
        """
        self.count = 1

        self.timer_period = 5
        self.timer = self.create_timer(self.timer_period, self.timer_callback)
        #create_timer()是Node类的一个方法，用于创建一个定时器对象，第一个参数是定时器周期，单位是秒，第二个参数是定时器回调函数
        #create_timer()方法会返回一个定时器对象，这个对象会在指定的周期内调用指定的回调函数，从而实现定时任务的功能。
        #create_timer.cancel()方法可以取消定时器，停止定时任务的执行。通常用于回调函数的后面来取消定时器，或者在节点关闭时取消定时器，避免定时器继续运行。这样就可以实现定时器的动态控制（如单次通信），根据需要启动或停止定时任务。
        self.account = 80
        self.sub_money = self.create_subscription(UInt32,"sexy_girl_money",self.recv_money_callback,10)
        #create_subscription()是Node类的一个方法，用于创建一个订阅者对象，第一个参数是消息类型，第二个参数是话题名称，第三个参数是订阅者回调函数，第四个参数是队列大小
        #create_subscription()方法会返回一个订阅者对象，这个对象会在接收到指定话题的消息时调用指定的回调函数，从而实现订阅任务的功能。
        #消息类型包含了消息的结构和数据类型，话题名称是用于标识消息的主题，订阅者回调函数是用于处理接收到的消息，队列大小是用于控制接收消息的缓存大小。
        """这个和下面那个是我自己编novel接受者函数，String的对应的消息类型是：std_msgs/msg/String ，可以通过命令ros2 topic info /get_novel查到
        self.sub_money=self.create_subscription(String,"get_novel",self.getnovel_callback,10)
        """
        self.borrow_server=self.create_service(BorrowMoney,"borrow_money",self.Borrow_money_callback)
        #声明参数
        self.declare_parameter("writer_timer_period",5)

    def Borrow_money_callback(self,request,response):
        #request是来自客户端的请求数据
        #response是服务端的相应数据
        self.get_logger().info("是%s要借钱，要借%d元,账户目前有%d元"% (request.name,request.money,self.account))
        if request.money*10<=self.account:
            response.success = True
            response.money = request.money
            self.account -= request.money
            self.get_logger().info("已向%s借出%d元，目前还剩%d元" % (request.name,response.money,self.account))
        else:
            response.success = False
            response.money = 0
            self.get_logger().info("钱不够了，不借")
        return response

    def timer_callback(self):

        msg = String()#导入消息类型（msg 本质上是一组结构化数据的定义模板。
                      #在 ROS 2 的话题（Topic）通信中，发布者（Publisher）和订阅者（Subscriber）必须使用完全相同的 msg 类型，才能成功传递信息）
        msg.data="第%d回：潋言湖，第%d次遇见她"%(self.count,self.count)#format格式,data是被String()声明后的一个属性
        self.pub_novel.publish(msg)
        self.get_logger().info("发布了一个章节的小说，内容是：%s"%msg.data)
        self.count+=1
        timer_period = self.get_parameter("writer_timer_period").get_parameter_value().integer_value
        self.timer.timer_period_ns = timer_period * (1000*1000*1000)

    def recv_money_callback(self,money):
        self.account += money.data
        self.get_logger().info("收到%s元钱，当前账户余额为：%d"%(money.data,self.account))
    """使用ros2 topic pub /get_novel std_msg/msg/String "{data:  '***'}"进行自行发布话题
    def getnovel_callback(self,chapter):
        self.get_logger().info("我已经收到小说，正在看第%s章"%(chapter.data))
    """

def main(args=None):#入口函数
    print("debugg:running file is:",os.path.abspath(__file__))
    rclpy.init(args=args)#初始化客户端库
    li4_node=WriterNode("li4")#新建节点对象
    rclpy.spin(li4_node)#spin循环节点
    rclpy.shutdown()#关闭客户端库